<template>
  <t-drawer
    v-model:visible="visible"
    :footer="false"
    size="medium"
    class="edit-node-compo"
    prevent-scroll-through
    show-in-attached-element
    :header="false"
    :show-overlay="true"
    @close="handlerClose"
  >
    <header class="header">
      <div class="icon">
        <img :src="nodeCfg?.icon" :alt="nodeCfg?.type" />
      </div>
      <div class="title-editor">
        <span class="label"> {{ nodeCfg.group }} </span>
      </div>
      <div class="title-operation">
        <CloseCircleIcon size="24" @click="close" />
      </div>
    </header>

    <!-- <span class="value">
      {{ modelData.nodeData.nodeName }}
    </span>
    <span class="title-editor-operation">
      <t-button shape="square" variant="text">
        <template #icon> <Edit2Icon size="20" /> </template>
      </t-button>
    </span>

    <div>
      {{ modelData }}
    </div> -->
    <section class="form-section">
      <t-form :data="formData" label-align="left" :label-width="80">
        <t-form-item
          :rules="[
            {
              required: true,
              message: '不能为空',
              trigger: 'blur',
            },
          ]"
          label="节点名称"
          name="name"
        >
          <t-input v-model="formData.nodeName"></t-input>
        </t-form-item>
      </t-form>
      <t-divider></t-divider>

      <!-- 编辑 branches -->
      <t-form
        v-if="nodeCfg.canEditRelation"
        ref="formValidatorStatus"
        :data="formData"
        :label-width="80"
        :status-icon="true"
        @reset="onReset"
      >
        <div
          v-for="(item, index) in formData.branches"
          :key="item.id"
          style="padding: 0px 24px 30px 0"
        >
          <t-form-item
            label="条件组"
            :name="`branches[${index}].name`"
            :rules="[
              {
                required: true,
                message: '不能为空',
                trigger: 'blur',
              },
            ]"
          >
            <t-space>
              <t-input v-model="formData.branches[index].name"></t-input>
              <t-button
                theme="default"
                :disabled="formData.branches.length <= 1"
                @click="deleteRelation(index)"
              >
                删除
              </t-button>
            </t-space>
          </t-form-item>
        </div>
        <t-form-item
          name="branches"
          :rules="relationListRules"
          label-width="0"
          :status-icon="false"
        >
        </t-form-item>
        <!-- 当规则数目不是 0 的时候，说明需要规则 -->
        <t-form-item v-if="nodeCfg.canEditRelation" :status-icon="false">
          <t-space size="small">
            <t-button theme="default" @click="addRelation">添加规则</t-button>
          </t-space>
        </t-form-item>
        <!-- https://tdesign.woa.com/react/components/form -->
      </t-form>
    </section>
  </t-drawer>
</template>

<script lang="ts" setup>
import { nextTick, reactive, ref, toValue, watch, computed } from "vue";
import { FormInstanceFunctions, MessagePlugin } from "tdesign-vue-next";
import { CloseCircleIcon, Edit2Icon } from "tdesign-icons-vue-next";

import _ from "lodash";
import { getRelationUUID } from "@/utils";
import { formatXGraphLabel } from "@/utils/xgraph-util";
const emit = defineEmits(["submit", "close"]);

const props = defineProps<{
  nodeList: Array<{
    group: string;
    type: string;
    icon: string;
    pIcon: string;
    canEditRelation?: boolean;
  }>;
}>();

type Model = {
  id: string;
  label: string;
  nodeData: {
    nodeName: string;
    nodeType: string;
    branches: Array<{ name: string; id: string }>;
  };
  type: string;
  x: number;
  y: number;
};

const formValidatorStatus = ref<FormInstanceFunctions>(null as any);
const visible = ref(false);

const modelData = ref<Model>({
  id: "",
  label: "",
  nodeData: {
    nodeName: "",
    nodeType: "",
    branches: [],
  },
  type: "",
  x: 0,
  y: 0,
});

const nodeCfg = computed(() => {
  return (
    props.nodeList.find((v) => {
      return v.type === modelData.value.nodeData.nodeType;
    }) || props.nodeList[0]
  );
});

const formData = reactive<{
  branches: Model["nodeData"]["branches"];
  nodeName: string;
}>({
  branches: [],
  nodeName: "",
});

// TODO: 思考下需不需要验证 relation Length ，因为默认给了一个空，所以长度大概率不会低于 1 条
const relationListRules = [
  {
    message: "不能为空",
    validator(v) {
      return v.length >= 1;
    },
  },
];

const open = async (cfg: Model) => {
  visible.value = true;
  modelData.value = cfg;
  formData.branches = cfg.nodeData.branches || [];
  formData.nodeName = cfg.nodeData.nodeName || "";
  await nextTick();
  if (formValidatorStatus.value) {
    formValidatorStatus.value.validate();
  }
};

const addRelation = () => {
  formData.branches.push({
    id: getRelationUUID(),
    name: "",
  });
};

const deleteRelation = (index: number) => {
  formData.branches.splice(index, 1);
};

const onReset = () => {
  MessagePlugin.success("重置成功");
};

const submitForm = () => {
  emit(
    "submit",
    _.mergeWith(
      {},
      _.cloneDeep(modelData.value),
      {
        label: formatXGraphLabel(formData.nodeName),
        nodeData: _.cloneDeep(formData),
      },
      (source, target) => {
        if (_.isArray(source)) {
          return target;
        }
      }
    )
  );
};

watch(formData, (newVal, oldVal) => {
  submitForm();
});

const handlerClose = () => {
  emit(
    "close",
    _.mergeWith(
      {},
      _.cloneDeep(modelData.value),
      {
        label: formatXGraphLabel(formData.nodeName),
        nodeData: _.cloneDeep(formData),
      },
      (source, target) => {
        if (_.isArray(source)) {
          return target;
        }
      }
    )
  );
};

const close = () => {
  if (modelData.value) {
    handlerClose();
    modelData.value = {
      id: "",
      label: "",
      nodeData: {
        nodeName: "",
        nodeType: "",
        branches: [],
      },
      type: "",
      x: 0,
      y: 0,
    };
    formData.branches = [];
    visible.value = false;
  }
};

defineExpose({
  open,
  close,
});
</script>
