<template>
  <qa-tree
    ref="qaTreeRef"
    :g-config="gConfig"
    :init-json="initJson"
    @graphEvent="handlerGraphEvent"
  ></qa-tree>
</template>
<script lang="ts">
import QaTree from "./flow/QaTree.vue";
import { Ref, ref } from "vue";

interface Data {
  initJson: Ref<string>;
  fn?: (...args: any[]) => any;
}
export default {
  components: {
    QaTree,
  },
  props: {
    gConfig: {
      required: true,
      type: Object,
    },
  },
  setup(): Data {
    const initJson = ref("{}");
    return {
      initJson,
      fn: undefined,
    };
  },
  methods: {
    /**
     * @description
     ** 向外暴露的 API ，添加事件功能
     */
    addEvent(fn: (...args: any[]) => any) {
      this.fn = fn;
    },
    handlerGraphEvent({ type, payload }) {
      if (this.fn) {
        this.fn(type, payload);
      }
    },
    /**
     * @description 向外暴露的 API ，设置数据事件
     */
    readData(jsonData: string) {
      this.initJson = jsonData;
      const qaTreeRef = this.$refs.qaTreeRef as (typeof QaTree)["methods"];

      if (qaTreeRef) {
        qaTreeRef.draw(JSON.parse(jsonData));
      }
    },
  },
};
</script>
