<!-- 小窗口 -->

<template>
  <div class="tool">
    <!-- <div class="minimap-button" @click="handleToggle">
      {{ minimapVisible ? "⬆" : "⬇" }}
    </div> -->
    <div ref="minimap" class="minimap-container">
      <div id="minimap" class="minimap"></div>
    </div>
    <div class="zoom-tool">
      <!-- <button class="button" :disabled="zoom <= 10" @click="zoomOut">➖</button>
      <div class="zoom">{{ zoom }}%</div>
      <button class="button" :disabled="zoom >= 200" @click="zoomIn">➕</button> -->
      <t-input-number
        :step="10"
        :value="zoom"
        :max="200"
        :mim="10"
        align="right"
        suffix="%"
        @change="handlerRoomChange"
      />

      <t-button shape="square" variant="text" @click="zoomReset">
        <template #icon><ArtboardIcon /></template>
      </t-button>
      <t-button shape="square" variant="text" @click="handleClickLayout(true)">
        <template #icon><GestureApplauseIcon /></template>
      </t-button>
      <t-button shape="square" variant="text" @click="centerGraph">
        <template #icon><CenterFocusStrongIcon /></template>
      </t-button>
      <t-button shape="square" variant="text" @click="handlerSave">
        <template #icon><SaveIcon /></template>
      </t-button>

      <!-- <button class="button" @click="focusStart(NODE_TYPE.startNode.id)">🔘</button> -->
    </div>
  </div>
</template>

<script>
import _ from "lodash";
import {
  CenterFocusStrongIcon,
  ArtboardIcon,
  SaveIcon,
  GestureApplauseIcon,
} from "tdesign-icons-vue-next";
export default {
  name: "CanvasZoom",
  components: {
    ArtboardIcon,
    CenterFocusStrongIcon,
    SaveIcon,
    GestureApplauseIcon,
  },
  props: {
    graph: {
      type: Object,
      default: null,
    },
  },
  emits: ["handlerSave", "handleClickLayout", "centerGraph"],
  data() {
    return {
      zoom: 100,
      zoomRate: 10,
      initEd: false,
      minimapVisible: true, // 缩略图是否可见
    };
  },
  computed: {
    debounceFocusStart() {
      return _.debounce(this.focusStart, 650);
    },
  },
  watch: {
    graph() {
      this.init();
    },
    minimapVisible(v) {
      this.$refs.minimap.style.height = v ? "auto" : "0";
    },
  },
  mounted() {
    this.init();
  },
  unmounted() {
    this.destroy();
  },
  methods: {
    destroy() {
      this.graph.off("viewportchange", this.handlerViewportChange);
    },
    init() {
      if (this.graph) {
        this.initEd = true;
        this.zoom = Math.round(this.graph.getZoom() * 100);
        this.graph.on("viewportchange", this.handlerViewportChange);
      }
    },
    handlerViewportChange(e) {
      this.zoom = _.ceil(this.graph.getZoom() * 100, 0);
    },
    handleToggle() {
      this.minimapVisible = !this.minimapVisible;
    },
    changeGraphZoom(value) {
      this.graph.zoomTo(value / 100, false, false);
    },
    handlerRoomChange(v) {
      const newV = _.clamp(200, 10, v);
      this.changeGraphZoom(newV);
    },
    zoomReset() {
      this.changeGraphZoom(100);
      this.debounceFocusStart();
    },
    focusStart(id = "startNode") {
      const startNode = this.graph.findById(id);
      if (startNode) {
        this.graph.focusItem(startNode, false);
      }
    },
    handlerSave() {
      this.$emit("handlerSave");
    },
    handleClickLayout(v) {
      this.$emit("handleClickLayout", v);
    },
    centerGraph() {
      this.$emit("centerGraph");
    },
  },
};
</script>

